<?php
namespace App\Services;
use App\Models\SocialPost;use Illuminate\Support\Facades\DB;use RuntimeException;
final class ApprovalService {public function __construct(private ContentFingerprint $fingerprint){}public function submit(SocialPost $p):SocialPost{if($p->status!=='draft')throw new RuntimeException('Only draft content can be submitted for review.');$this->assertComplete($p);$p->update(['status'=>'pending_review']);return $p->refresh();}public function approve(SocialPost $p,string $reviewer){return DB::transaction(function()use($p,$reviewer){$locked=SocialPost::query()->lockForUpdate()->findOrFail($p->id);if($locked->status!=='pending_review')throw new RuntimeException('Only content pending review can be approved.');$this->assertComplete($locked);$approval=$locked->approvals()->create(['version'=>$locked->version,'fingerprint'=>$this->fingerprint->for($locked),'approved_by'=>$reviewer,'approved_at'=>now()]);$locked->update(['status'=>'approved']);return $approval;});}public function assertComplete(SocialPost $p):void{if(blank($p->title)||blank($p->body))throw new RuntimeException('Title and body are required.');if(blank($p->media_reference))throw new RuntimeException('Media reference is required.');if(empty($p->channels))throw new RuntimeException('At least one channel is required.');if(!$p->scheduled_at)throw new RuntimeException('Scheduled date is required.');}}